const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const icons={pin:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',car:'<path d="m4 10 2-6h12l2 6M3 11h18v7H3zM5 18v3m14-3v3M7 14h1m8 0h1M5 10h14"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6z"/><path d="m8 12 3 3 5-6"/>',filter:'<path d="M4 6h16M7 12h10m-7 6h4"/><circle cx="8" cy="6" r="2" fill="currentColor" stroke="none"/><circle cx="15" cy="12" r="2" fill="currentColor" stroke="none"/>',user:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-3a7 7 0 0 1 14 0v3"/>',gear:'<path d="M6 3v12m12-12v6M6 9h12m-6 0v12"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="12" r="3"/>',fuel:'<path d="M4 21V4h10v17M3 21h12M4 10h10m0-4h3l3 4v7a2 2 0 0 1-4 0v-3h-2"/>',compare:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',key:'<circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-3-3 3-3m-6 0 3-3"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>'};
const svg=(key)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[key]||icons.car}</svg>`;
function hydrateIcons(root=document){$$('[data-icon]',root).forEach(el=>el.innerHTML=svg(el.dataset.icon));}hydrateIcons();
const carSketch=(type)=>`<svg viewBox="0 0 68 34" aria-hidden="true"><path d="M5 23v-7l8-3 7-8h24l10 10 8 3v8H5z"/><path d="M18 13h29L41 7H24zM33 7v6M9 20h5m41 0h4"/><circle cx="18" cy="26" r="5" fill="var(--bg)"/><circle cx="50" cy="26" r="5" fill="var(--bg)"/>${type==='electric'?'<path d="m34 17-4 6h5l-2 5"/>':''}${type==='suv'||type==='family'?'<path d="M18 3h28m-27 2V3m25 2V3"/>':''}</svg>`;
const categories=[['economy','اقتصادية','لمشاوير كل يوم'],['sedan','سيدان','راحة وأناقة'],['suv','دفع رباعي','جاهزة للمغامرة'],['luxury','فاخرة','كل مشوار مميّز'],['electric','كهربائية','خيار للمستقبل'],['family','عائلية','مكان لكل العيلة']];
const companies=[['رِحال لتأجير السيارات','RIHAL','الشميساني','#1b5944'],['مسار لتأجير السيارات','masar.','الصويفية','#c97936'],['درب لتأجير السيارات','DARB','مطار الملكة علياء','#353d66'],['وجهة لتأجير السيارات','wijha','عبدون','#4c7166'],['مدى لتأجير السيارات','MADA','خلدا','#75894b'],['مِشوار لتأجير السيارات','MISHWAR','الشميساني','#b55f4d'],['أفق لتأجير السيارات','OFOQ','الصويفية','#457385'],['لين لتأجير السيارات','LEEN','عبدون','#8f6d95'],['رحلة لتأجير السيارات','RIHLA','مطار الملكة علياء','#988143'],['خطوة لتأجير السيارات','KHOTWA','خلدا','#577e69'],['بوابة عمّان','GATE','الشميساني','#374f76'],['سند لتأجير السيارات','SANAD','الصويفية','#a16e4c'],['دوار لتأجير السيارات','DAWWAR','عبدون','#4c8184'],['جبل لتأجير السيارات','JABAL','خلدا','#6c755a'],['ساحة لتأجير السيارات','SAHA','مطار الملكة علياء','#937954'],['تلال لتأجير السيارات','TILAL','الصويفية','#755f86'],['انطلاق لتأجير السيارات','GO.','الشميساني','#42745e'],['دليل لتأجير السيارات','DALEEL','مطار الملكة علياء','#49749c']].map((x,id)=>({id,name:x[0],logo:x[1],location:x[2],color:x[3]}));
const models=[['هيونداي إلنترا','Hyundai Elantra','sedan',26,'sedan',5,'بنزين'],['كيا بيكانتو','Kia Picanto','economy',18,'compact',5,'بنزين'],['مرسيدس C-Class','Mercedes-Benz C-Class','luxury',65,'mercedes',5,'بنزين'],['تويوتا RAV4','Toyota RAV4','suv',45,'suv',5,'هايبرد'],['BMW الفئة الخامسة','BMW 5 Series','luxury',85,'bmw',5,'بنزين'],['تسلا موديل 3','Tesla Model 3','electric',48,'tesla',5,'كهرباء'],['تويوتا كورولا','Toyota Corolla','sedan',28,'sedan',5,'هايبرد'],['كيا سبورتاج','Kia Sportage','suv',42,'suv',5,'بنزين'],['هيونداي أكسنت','Hyundai Accent','economy',22,'compact',5,'بنزين'],['كيا كارنفال','Kia Carnival','family',58,'family',7,'ديزل'],['هيونداي أيونيك','Hyundai Ioniq','electric',35,'tesla',5,'كهرباء'],['تويوتا برادو','Toyota Prado','family',78,'suv',7,'بنزين']];
const cars=Array.from({length:36},(_,id)=>{const m=models[id%12];return {id,name:m[0],en:m[1],category:m[2],price:m[3]+Math.floor(id/12)*3,image:`assets/${m[4]}.jpg`,seats:m[5],fuel:m[6],companyId:id%18,year:2024+(id%3===0?1:0),deposit:m[2]==='luxury'?300:150,km:200,idNumber:`AD-${String(id+1).padStart(4,'0')}`}});
function readStored(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function saveStored(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('التخزين غير متاح في هذا المتصفح. تقدر تنزّل نسخة من طلبك.');return false;}}
let favorites=new Set(readStored('amman-favorites',[]).filter(id=>cars.some(c=>c.id===id))),compared=new Set(),shown=6;
let state={category:'all',location:'all',company:'all',budget:150,keyword:'',sort:'featured',favorites:false};
const pickup=$('#pickup'),ret=$('#return');
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function addDay(value,n){const d=new Date(value+'T12:00:00');d.setDate(d.getDate()+n);return localDate(d);}
const today=localDate(new Date());pickup.min=today;pickup.value=addDay(today,1);ret.value=addDay(today,4);ret.min=addDay(pickup.value,1);
function daysBetween(a,b){return Math.round((Date.parse(b+'T12:00:00Z')-Date.parse(a+'T12:00:00Z'))/86400000);}
pickup.addEventListener('change',()=>{ret.min=addDay(pickup.value,1);if(ret.value<=pickup.value)ret.value=ret.min;});
$('#year').textContent=new Date().getFullYear();
$('#categories').innerHTML=categories.map(([id,label,sub])=>`<button class="category-card" data-category="${id}" aria-pressed="false">${carSketch(id)}<span><b>${label}</b><small>${sub}</small></span></button>`).join('');
$('#company-filter').insertAdjacentHTML('beforeend',companies.map(c=>`<option value="${c.id}">${c.name}</option>`).join(''));
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function card(c){const company=companies[c.companyId],category=categories.find(x=>x[0]===c.category)[1];return `<article class="car-card"><div class="car-image"><img src="${c.image}" alt="صورة توضيحية لفئة ${category}" loading="lazy"><span class="car-badge ${c.id%3===0?'lime':''}">${c.id%3===0?'اختيار مميّز':category}</span><button class="heart-btn ${favorites.has(c.id)?'saved':''}" data-favorite="${c.id}" aria-label="${favorites.has(c.id)?'إزالة من':'إضافة إلى'} المفضلة" aria-pressed="${favorites.has(c.id)}">${svg('heart')}</button><span class="illustrative">صورة توضيحية للفئة</span></div><div class="car-body"><div class="car-heading"><h3>${c.name}</h3><span class="car-year">${c.year}</span></div><p class="car-subtitle">${c.en} · أو ما يماثلها</p><div class="car-specs"><span>${svg('gear')} أوتوماتيك</span><span>${svg('user')} ${c.seats} ركاب</span><span>${svg(c.fuel==='كهرباء'?'bolt':'fuel')} ${c.fuel}</span></div><div class="dealer-row"><button class="dealer-name" data-company="${company.id}"><span>${company.logo.slice(0,1)}</span>${company.name}</button><small>${svg('pin')} ${company.location.replace('مطار الملكة علياء','المطار')}</small></div><div class="car-bottom"><div class="price"><b>${c.price}</b> د.أ <span>/ يوم</span><small>سعر توضيحي · غير قابل للحجز الفعلي</small></div><button class="detail-btn" data-detail="${c.id}">التفاصيل <span>←</span></button></div><label class="compare-label"><input type="checkbox" data-compare="${c.id}" ${compared.has(c.id)?'checked':''}> أضف للمقارنة</label></div></article>`;}
function filtered(){let results=cars.filter(c=>(state.category==='all'||c.category===state.category)&&(state.location==='all'||companies[c.companyId].location===state.location)&&(state.company==='all'||c.companyId===Number(state.company))&&c.price<=state.budget&&(!state.keyword||`${c.name} ${c.en} ${companies[c.companyId].name}`.toLowerCase().includes(state.keyword.toLowerCase()))&&(!state.favorites||favorites.has(c.id)));if(state.sort==='low')results.sort((a,b)=>a.price-b.price);if(state.sort==='high')results.sort((a,b)=>b.price-a.price);return results;}
function render(){const list=filtered();$('#car-grid').innerHTML=list.length?list.slice(0,shown).map(card).join(''):`<div class="empty-state"><h3>${state.favorites?'ما في سيارات بالمفضلة لسه':'ما لقينا سيارات بهالخيارات'}</h3><p>${state.favorites?'اضغط على القلب بجانب أي سيارة لحفظها هون.':'جرّب توسّع الميزانية أو تغيّر مكان الاستلام.'}</p><button class="button small" data-reset>استعرض كل السيارات</button></div>`;$('#shown-count').textContent=`عرض ${Math.min(shown,list.length)} من ${list.length} سيارة تجريبية`;$('#load-more').hidden=shown>=list.length;$('#fav-count').textContent=favorites.size;$('#cars-title').innerHTML=(state.favorites?'سياراتك المفضلة':state.company!=='all'?companies[Number(state.company)].name:'سيارات لمشوارك القادم')+'<span class="accent-dot">.</span>';$('#active-summary').textContent=(state.category!=='all'||state.location!=='all'||state.company!=='all'||state.keyword||state.budget<150||state.favorites)?`${list.length} نتيجة${state.location!=='all'?' · '+state.location:''} · ${daysBetween(pickup.value,ret.value)} أيام` :'';$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.category));$$('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===state.category);b.setAttribute('aria-pressed',b.dataset.category===state.category);});$('#filter-count').textContent=[state.company!=='all',state.budget<150,!!state.keyword].filter(Boolean).length||'';}
function reset(){state={category:'all',location:'all',company:'all',budget:150,keyword:'',sort:'featured',favorites:false};shown=6;$('#company-filter').value='all';$('#budget').value=150;$('#budget-label').textContent='150 د.أ';$('#keyword').value='';$('#sort').value='featured';$('#location').value='all';$('#search-category').value='all';render();}
function scrollCars(){$('#cars').scrollIntoView({behavior:'smooth'});}
$('#search-form').addEventListener('submit',e=>{e.preventDefault();if(daysBetween(pickup.value,ret.value)<1){toast('اختار تاريخ تسليم بعد تاريخ الاستلام');return;}state.location=$('#location').value;state.category=$('#search-category').value;state.favorites=false;shown=6;$('#results-description').textContent=`من ${pickup.value} إلى ${ret.value} · الأسعار والتوفر توضيحيان`;render();scrollCars();});
$('#categories').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(b){state.category=b.dataset.category;state.favorites=false;$('#search-category').value=state.category;shown=6;render();scrollCars();}});
$$('[data-tab]').forEach(b=>b.onclick=()=>{state.category=b.dataset.tab;$('#search-category').value=state.category;shown=6;render();});
$('#filter-btn').onclick=()=>{$('#filter-panel').hidden=!$('#filter-panel').hidden;$('#filter-btn').setAttribute('aria-expanded',!$('#filter-panel').hidden);};
$('#company-filter').onchange=e=>{state.company=e.target.value;shown=6;render();};$('#budget').oninput=e=>{state.budget=Number(e.target.value);$('#budget-label').textContent=state.budget+' د.أ';shown=6;render();};$('#keyword').oninput=e=>{state.keyword=e.target.value.trim();shown=6;render();};$('#sort').onchange=e=>{state.sort=e.target.value;render();};$('#reset-filters').onclick=reset;$('#all-cars').onclick=()=>{reset();shown=12;render();};$('#load-more').onclick=()=>{shown+=6;render();};$('#favorites-btn').onclick=()=>{reset();state.favorites=true;shown=36;render();scrollCars();};$('#menu-btn').onclick=()=>{const n=$('header nav');n.classList.toggle('open');$('#menu-btn').setAttribute('aria-expanded',n.classList.contains('open'));};$$('header nav a').forEach(a=>a.onclick=()=>{$('header nav').classList.remove('open');$('#menu-btn').setAttribute('aria-expanded','false');});
const modal=$('#modal');let previousFocus;
function openModal(html,eyebrow='عمّان درايف'){previousFocus=document.activeElement;$('#modal-content').innerHTML=html;$('#modal-eyebrow').textContent=eyebrow;hydrateIcons(modal);if(!modal.open)modal.showModal();modal.scrollTop=0;}
function closeModal(){modal.close();previousFocus?.focus?.();}
$('#close-modal').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function companyCard(c){const count=cars.filter(x=>x.companyId===c.id).length;return `<button class="company-card" data-company="${c.id}" style="--company-color:${c.color}"><span class="company-logo" dir="ltr">${c.logo}</span><h3>${c.name}</h3><p>${svg('pin')} ${c.location}</p><span><b>${count}</b> سيارات في النموذج <span>↗</span></span></button>`;}
$('#company-grid').innerHTML=companies.slice(0,6).map(companyCard).join('');$('#all-companies').onclick=()=>openModal(`<h2 class="modal-title">دليل شركات التأجير</h2><p class="modal-description">${companies.length} شركة توضيحية في أحياء عمّان والمطار. اختر شركة لاستعراض أسطولها.</p><div class="modal-company-grid">${companies.map(companyCard).join('')}</div>`,'شركات عمّان');
function showCompany(id){const c=companies[id];openModal(`<div class="company-profile"><div class="company-logo" dir="ltr" style="color:${c.color}">${c.logo}</div><h2>${c.name}</h2><p>${svg('pin')} عمّان · ${c.location}</p><span class="subnote">ملف شركة تجريبي — لا توجد شراكة أو بيانات تواصل فعلية.</span></div><h3>السيارات في النموذج</h3><div class="modal-favorites">${cars.filter(x=>x.companyId===id).map(card).join('')}</div>`,'دليل الشركات');}
function showDetail(id){const c=cars[id],company=companies[c.companyId];openModal(`<h2 class="modal-title">${c.name} <span class="car-year">${c.year}</span></h2><p class="modal-description">${c.en} أو ما يماثلها · ${company.name} · ${company.location}</p><img class="modal-car-image" src="${c.image}" alt="صورة توضيحية للفئة"><div class="detail-layout"><div><h3>تفاصيل المشوار</h3><ul><li>ناقل حركة أوتوماتيك · ${c.seats} ركاب · ${c.fuel}</li><li>المسافة اليومية: ${c.km} كم</li><li>وديعة مستردة توضيحية: ${c.deposit} د.أ</li><li>تأمين أساسي توضيحي، التفاصيل تؤكدها الشركة</li><li>مكان الاستلام: ${company.location}</li></ul><p class="subnote">هذا عرض تجريبي. صور السيارات توضيحية للفئة، والأسعار والشروط ليست عرضاً ملزماً من شركة فعلية.</p></div><form class="booking-box" id="booking-form"><label>تاريخ الاستلام<input type="date" id="detail-pickup" value="${pickup.value}" min="${today}" required></label><label>تاريخ التسليم<input type="date" id="detail-return" value="${ret.value}" min="${addDay(pickup.value,1)}" required></label><div class="cost-row"><span id="duration"></span><span><b id="total-price"></b> د.أ</span></div><p class="subnote">تكلفة المدة قبل الوديعة وأي إضافات. المبلغ توضيحي.</p><button class="button" type="submit">جهّز طلب الإيجار ←</button></form></div>`,'تفاصيل السيارة · '+c.idNumber);const p=$('#detail-pickup'),r=$('#detail-return');function updateCost(){const n=daysBetween(p.value,r.value);$('#duration').textContent=`${n>0?n:'—'} أيام × ${c.price} د.أ`;$('#total-price').textContent=n>0?n*c.price:'—';}p.onchange=()=>{r.min=addDay(p.value,1);if(r.value<=p.value)r.value=r.min;updateCost();};r.onchange=updateCost;updateCost();$('#booking-form').onsubmit=e=>{e.preventDefault();if(daysBetween(p.value,r.value)<1){toast('راجع تواريخ الرحلة');return;}showRequest(c,p.value,r.value);};}
const escapeText=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500);}
function showRequest(c,p,r){const n=daysBetween(p,r);openModal(`<h2 class="modal-title">جهّز طلب إيجارك</h2><p class="modal-description">أضف بياناتك لحفظ مسودة على جهازك. لن يُرسل أي طلب أو يُحجز أي مبلغ.</p><div class="request-summary">${c.name} · ${companies[c.companyId].name}<br>${p} ← ${r} · ${n} أيام<br>التكلفة التوضيحية: <b>${n*c.price} د.أ</b></div><form class="join-form" id="request-form"><label>الاسم الكامل<input name="name" autocomplete="name" required maxlength="100"></label><label>رقم الهاتف<input name="phone" type="tel" autocomplete="tel" placeholder="+962…" required minlength="7" maxlength="25" dir="ltr"></label><label class="full">البريد الإلكتروني (اختياري)<input name="email" type="email" autocomplete="email" maxlength="120" dir="ltr"></label><p class="subnote full">هذه مسودة تجريبية فقط. احذفها في أي وقت من سياسة الخصوصية. الحجز يتأكد عند تفعيل التواصل مع الشركات.</p><button class="button full" type="submit">احفظ مسودة الطلب</button></form>`,'طلب تجريبي');$('#request-form').onsubmit=e=>{e.preventDefault();const form=Object.fromEntries(new FormData(e.target)),draft={type:'demo-rental-request',...form,car:c.name,company:companies[c.companyId].name,pickup:p,return:r,days:n,totalJOD:n*c.price,created:new Date().toISOString(),status:'local-draft-not-sent'};const stored=saveStored('amman-rental-draft',draft);openModal(`<div class="success-block"><div class="success-mark">✓</div><h2 class="modal-title">${stored?'مسودة مشوارك جاهزة':'مسودة مشوارك جاهزة للتنزيل'}</h2><p>يا ${escapeText(form.name)}، ${stored?'حفظنا التفاصيل على هذا الجهاز.':'تقدر تحفظ نسخة من التفاصيل على جهازك.'} لم يُرسل طلب للشركة ولم يتم تأكيد حجز.</p><div class="request-summary">${c.name} · ${n} أيام · ${n*c.price} د.أ<br>${p} ← ${r}</div><button class="button" id="download-request">نزّل نسخة من المسودة ↓</button></div>`,'مسودة محلية');$('#download-request').onclick=()=>download('amman-rental-draft.json',draft);};}
function join(){const prior=readStored('amman-company-draft',{});openModal(`<h2 class="modal-title">خلّي شركتك جزء من المشوار.</h2><p class="modal-description">جهّز ملف شركتك للانضمام إلى عمّان درايف. هذه الاستمارة التجريبية تحفظ البيانات على جهازك فقط.</p><form class="join-form" id="join-form"><label>اسم الشركة<input name="company" required maxlength="100" value="${escapeText(prior.company||'')}"></label><label>اسم المسؤول<input name="contact" required maxlength="100" value="${escapeText(prior.contact||'')}"></label><label>البريد الإلكتروني<input name="email" type="email" autocomplete="email" required dir="ltr" maxlength="120" value="${escapeText(prior.email||'')}"></label><label>رقم الهاتف<input name="phone" type="tel" required minlength="7" maxlength="25" dir="ltr" value="${escapeText(prior.phone||'')}"></label><label>موقع الشركة<select name="location">${['الشميساني','الصويفية','عبدون','خلدا','مطار الملكة علياء','منطقة أخرى في عمّان'].map(x=>`<option ${x===prior.location?'selected':''}>${x}</option>`).join('')}</select></label><label>عدد السيارات<input name="fleet" type="number" min="1" max="5000" required value="${Number(prior.fleet)||''}"></label><p class="subnote full">لا تتم إضافة شركتك إلى الدليل أو إرسال بياناتك في هذه النسخة. حفظ الملف يجهّزه للربط الفعلي لاحقاً.</p><button class="button full" type="submit">احفظ ملف الشركة ←</button></form>`,'لشركات التأجير');$('#join-form').onsubmit=e=>{e.preventDefault();const draft={...Object.fromEntries(new FormData(e.target)),created:new Date().toISOString(),status:'local-draft-not-sent'},stored=saveStored('amman-company-draft',draft);openModal(`<div class="success-block"><div class="success-mark">✓</div><h2>ملف ${escapeText(draft.company)} جاهز</h2><p>${stored?'حُفظ الملف محلياً على جهازك.':'تقدر تنزّل ملف الشركة.'} لم يتم إرسال بيانات الشركة أو نشرها.</p><button id="download-company" class="button">نزّل ملف الشركة ↓</button></div>`,'ملف محلي');$('#download-company').onclick=()=>download('amman-company-draft.json',draft);};}
$('#join-btn').onclick=join;$('#partner-btn').onclick=join;
function updateCompare(){const bar=$('#compare-bar');bar.hidden=compared.size===0;$('#compare-count').textContent=compared.size;$('#show-compare').disabled=compared.size<2;$$('[data-compare]').forEach(i=>i.checked=compared.has(Number(i.dataset.compare)));}
$('#clear-compare').onclick=()=>{compared.clear();updateCompare();};$('#show-compare').onclick=()=>{const cs=[...compared].map(i=>cars[i]);if(cs.length<2)return;const row=(label,fn)=>`<tr><th>${label}</th>${cs.map(c=>`<td>${fn(c)}</td>`).join('')}</tr>`;openModal(`<h2 class="modal-title">قارن، واختار على راحتك.</h2><p class="modal-description">مقارنة عروض توضيحية · الأسعار اليومية بالدينار الأردني</p><div class="comparison-wrap"><table class="comparison"><thead><tr><th>السيارة</th>${cs.map(c=>`<td><img src="${c.image}" alt="صورة توضيحية"><strong>${c.name}</strong></td>`).join('')}</tr></thead><tbody>${row('السعر / يوم',c=>`<b>${c.price} د.أ</b>`)}${row('للمدة المختارة',c=>`${daysBetween(pickup.value,ret.value)*c.price} د.أ`)}${row('الشركة',c=>companies[c.companyId].name)}${row('الاستلام',c=>companies[c.companyId].location)}${row('الركاب',c=>c.seats)}${row('الوقود',c=>c.fuel)}${row('الوديعة',c=>c.deposit+' د.أ')}${row('المسافة اليومية',c=>c.km+' كم')}${row('التفاصيل',c=>`<button class="button small" data-detail="${c.id}">اختر السيارة ←</button>`)}</tbody></table></div>`,'مقارنة السيارات');};
document.addEventListener('click',e=>{const f=e.target.closest('[data-favorite]');if(f){const id=Number(f.dataset.favorite);if(favorites.has(id))favorites.delete(id);else favorites.add(id);saveStored('amman-favorites',[...favorites]);$$(`[data-favorite="${id}"]`).forEach(b=>{b.classList.toggle('saved',favorites.has(id));b.setAttribute('aria-pressed',favorites.has(id));b.setAttribute('aria-label',favorites.has(id)?'إزالة من المفضلة':'إضافة إلى المفضلة');});$('#fav-count').textContent=favorites.size;if(state.favorites)render();toast(favorites.has(id)?'انضافت السيارة للمفضلة':'تمت إزالة السيارة من المفضلة');return;}const d=e.target.closest('[data-detail]');if(d){showDetail(Number(d.dataset.detail));return;}const c=e.target.closest('[data-company]');if(c){showCompany(Number(c.dataset.company));return;}if(e.target.closest('[data-reset]'))reset();});
document.addEventListener('change',e=>{if(e.target.matches('[data-compare]')){const id=Number(e.target.dataset.compare);if(e.target.checked){if(compared.size===3){e.target.checked=false;toast('تقدر تقارن حتى 3 سيارات. احذف سيارة لإضافة غيرها.');return;}compared.add(id);}else compared.delete(id);updateCompare();}});
$('#privacy-btn').onclick=()=>{openModal('<h2 class="modal-title">خصوصيتك على الطريق</h2><p class="modal-description">هذا نموذج تجريبي لمنصة عمّان درايف. المفضلة ومسودات طلب الإيجار والانضمام تُحفظ في متصفحك على هذا الجهاز فقط. لا نرسل هذه البيانات إلى الشركات ولا نعالج حجوزات أو مدفوعات. تحميل خط الواجهة من Google Fonts يرسل طلباً إلى خدمة الخطوط. صور الموقع محفوظة ضمن الموقع.</p><h3>البيانات المحفوظة على الجهاز</h3><p class="subnote">تقدر تمسح المفضلة والمسودات من هنا. المسح لا يحذف الملفات التي نزلتها بنفسك.</p><button class="outline-button" id="delete-data">امسح البيانات المحلية</button>','الخصوصية');$('#delete-data').onclick=()=>{try{['amman-favorites','amman-rental-draft','amman-company-draft'].forEach(k=>localStorage.removeItem(k));favorites.clear();render();closeModal();toast('تم مسح البيانات المحلية');}catch{toast('تعذر الوصول إلى التخزين المحلي');}};};
render();
